@js:
url = String(result).replace("{{key}}", key);
var res = java.get(url, {Referer: baseUrl}), code = res.statusCode(),
link = res.header("Location") || res.url();
java.log(code)
if(code >= 301 && link){
	url = /^https?/.test(link) ? 
	link : baseUrl + link;
	src =java.ajax(url);
	//java.log(src)
	id = String(src).match(
		/name","(\w+)".*?value","(\d+)"/) || [];
		nds = `${id[1]}=${id[2]}`;
	//java.log(nds)
	j = org.jsoup.Jsoup.parse(src)
	s = j.select("form > input");
	body = `${s.attr("name")}=${s.attr("value")}&${nds}`;
	java.log(body)
	post = JSON.stringify({
  "body": String(body),
  "method": "POST"});
  url + ","+ post;
	}else result;

