ruleSearch.bookList:
@js:
let r = java.hexDecodeToString(result).split("#");
let key = r[0]
let page = r[1]
let list = [];
if (key.includes("@")) {
    let url = `${source.bookSourceUrl}search?wd=${key}&page=${page}`;
    let res = java.ajax(url);
    list = JSON.parse(res).data?.books;
} else {
    let p = ["番茄", "七猫", "猫眼", "得间", "书旗", "滴滴"];
    let urls = p.map(x => `${source.bookSourceUrl}search?wd=${key}@${x}&page=1`);
    let res = java.ajaxAll(urls).map(x => JSON.parse(x.body()).data?.books);

    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < res.length; j++) {
            if (res[j] && res[j][i]) {
                list.push(res[j][i]);
            }
        }
    }
}
list.map(x=>JSON.stringify(x));

ruleContent.content:
@js:
let url = java.hexDecodeToString(result);
let w = String("a3B6c9D2E5F8").replace(/a|6|9|2|E|8/g, "");
let response = java.ajax(url + "&key=" + Map("密钥") + "&ban=" + w);

let content = JSON.parse(response).data.content;

let md5Regex = /"md5":"([a-f0-9]+)"/g;
let md5Values = [];
let match;

while ((match = md5Regex.exec(content)) !== null) {
    md5Values.push(match[1]);
}
if (md5Values.length > 0)
    content = md5Values.map(md5 => `<img src="https://p6-novel.byteimg.com/origin/novel-pic/${md5}">`).join("");

content;

